import fs from 'node:fs';
import path from 'node:path';

import { afterEach, describe, expect, it } from '@jest/globals';

import { CollectionRegistry } from '../../src/core/collections.js';
import { BRU_COLLECTION, ISOLATED_CONFIG, makeTempDir, removeTempDirs, writeFiles } from '../helpers.js';

const registry = new CollectionRegistry(ISOLATED_CONFIG);

const REQUEST = 'meta {\n  name: Ping\n  type: http\n  seq: 1\n}\n\nget {\n  url: http://localhost/ping\n}\n';

afterEach(removeTempDirs);

describe('CollectionRegistry.resolveFolderPath', () => {
  it('resolves a folder that contains requests', () => {
    expect(registry.resolveFolderPath(BRU_COLLECTION, 'users')).toBe(path.join(BRU_COLLECTION, 'users'));
    expect(registry.resolveFolderPath(BRU_COLLECTION, 'users/')).toBe(path.join(BRU_COLLECTION, 'users'));
  });

  it('resolves a nested folder', () => {
    const collection = writeFiles(makeTempDir(), { 'bruno.json': '{}', 'api/v1/ping.bru': REQUEST });

    expect(registry.resolveFolderPath(collection, 'api')).toBe(path.join(collection, 'api'));
    expect(registry.resolveFolderPath(collection, 'api/v1')).toBe(path.join(collection, 'api', 'v1'));
  });

  it.each([
    ['a request file', 'health.bru'],
    ['the collection root', '.'],
    ['the environments folder', 'environments'],
    ['a path outside the collection', '../yml-collection'],
    ['a folder that does not exist', 'nope'],
    ['a folder name in the wrong case', 'Users']
  ])('rejects %s', (_label, relativePath) => {
    expect(registry.resolveFolderPath(BRU_COLLECTION, relativePath)).toBeNull();
  });

  it.each(['empty', 'node_modules', '.git'])('rejects the "%s" folder, which list_requests and bru run skip', (folder) => {
    const collection = writeFiles(makeTempDir(), {
      'bruno.json': '{}',
      'ping.bru': REQUEST,
      'node_modules/dep/ping.bru': REQUEST,
      '.git/ping.bru': REQUEST
    });
    fs.mkdirSync(path.join(collection, 'empty'));

    expect(registry.resolveFolderPath(collection, folder)).toBeNull();
  });

  it('rejects a symlinked folder, even one pointing inside the collection', () => {
    const collection = writeFiles(makeTempDir(), { 'bruno.json': '{}', 'real/ping.bru': REQUEST });
    fs.symlinkSync(path.join(collection, 'real'), path.join(collection, 'linked'), 'dir');

    expect(registry.resolveFolderPath(collection, 'real')).toBe(path.join(collection, 'real'));
    expect(registry.resolveFolderPath(collection, 'linked')).toBeNull();
  });

  it('keeps resolving folders when a folder.bru is malformed', () => {
    const collection = writeFiles(makeTempDir(), {
      'bruno.json': '{}',
      'users/folder.bru': 'meta {\n  name: Users\n',
      'users/ping.bru': REQUEST
    });

    expect(registry.resolveFolderPath(collection, 'users')).toBe(path.join(collection, 'users'));
  });

  it('returns null for a directory that is not a collection', () => {
    expect(registry.resolveFolderPath(makeTempDir(), 'users')).toBeNull();
  });
});

describe('CollectionRegistry.environmentFiles', () => {
  it('lists the collection environments', () => {
    const names = registry.environmentFiles(BRU_COLLECTION).map((env) => env.name).sort();
    expect(names).toEqual(['local', 'staging']);
  });

  it('returns an empty list for an unknown collection', () => {
    expect(registry.environmentFiles(makeTempDir())).toEqual([]);
  });
});

import fs from 'node:fs';
import path from 'node:path';

import { afterEach, describe, expect, it } from '@jest/globals';

import { listEnvironmentFiles, readEnvironmentVariables, REDACTED } from '../../src/core/environments.js';
import { BRU_COLLECTION, YML_COLLECTION, makeTempDir, removeTempDirs, writeFiles } from '../helpers.js';

afterEach(removeTempDirs);

const ENVIRONMENT_FILES = {
  'environments/local.bru': 'vars {\n  a: 1\n}\n',
  'environments/dev.yml': 'name: dev\nvariables: []\n',
  'environments/notes.txt': 'not an environment',
  'environments/.DS_Store': ''
};

describe('listEnvironmentFiles', () => {
  it('lists only .bru environments in a .bru collection', () => {
    const dir = writeFiles(makeTempDir(), { 'bruno.json': '{"version":"1","name":"Bru"}', ...ENVIRONMENT_FILES });

    expect(listEnvironmentFiles(dir)).toEqual([
      { name: 'local', path: path.join(dir, 'environments', 'local.bru'), format: 'bru' }
    ]);
  });

  it('lists only .yml environments in a .yml collection', () => {
    const dir = writeFiles(makeTempDir(), { 'opencollection.yml': 'info:\n  name: Yml\n', ...ENVIRONMENT_FILES });

    expect(listEnvironmentFiles(dir)).toEqual([
      { name: 'dev', path: path.join(dir, 'environments', 'dev.yml'), format: 'yml' }
    ]);
  });

  it('returns an empty list when the collection has no environments folder', () => {
    expect(listEnvironmentFiles(writeFiles(makeTempDir(), { 'bruno.json': '{}' }))).toEqual([]);
  });

  it('returns an empty list for a directory that is not a collection', () => {
    expect(listEnvironmentFiles(writeFiles(makeTempDir(), ENVIRONMENT_FILES))).toEqual([]);
  });
});

describe('readEnvironmentVariables', () => {
  const envFile = (collectionPath: string, name: string) =>
    listEnvironmentFiles(collectionPath).find((env) => env.name === name)!;

  it('reads .bru variables, including disabled ones, and redacts secrets', async () => {
    expect(await readEnvironmentVariables(envFile(BRU_COLLECTION, 'local'))).toEqual([
      { name: 'baseUrl', value: 'http://127.0.0.1:1', enabled: true, secret: false },
      { name: 'legacyUrl', value: 'http://legacy.local', enabled: false, secret: false },
      { name: 'userId', value: '42', enabled: true, secret: false },
      { name: 'apiKey', value: REDACTED, enabled: true, secret: true }
    ]);
  });

  it('redacts a .yml secret even when its value is stored on disk', async () => {
    const env = envFile(YML_COLLECTION, 'dev');
    expect(fs.readFileSync(env.path, 'utf8')).toContain('do-not-leak');

    const variables = await readEnvironmentVariables(env);

    expect(variables).toEqual([
      { name: 'baseUrl', value: 'http://127.0.0.1:1', enabled: true, secret: false },
      { name: 'token', value: REDACTED, enabled: true, secret: true },
      { name: 'debug', value: 'true', enabled: false, secret: false }
    ]);
    expect(JSON.stringify(variables)).not.toContain('do-not-leak');
  });

  it('rejects on a malformed .bru environment instead of leaving an unhandled rejection', async () => {
    const dir = writeFiles(makeTempDir(), {
      'bruno.json': '{"version":"1","name":"Broken"}',
      'environments/broken.bru': 'vars {\n  baseUrl: x\n'
    });

    await expect(readEnvironmentVariables(envFile(dir, 'broken'))).rejects.toThrow();
  });
});

import path from 'node:path';

import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, jest } from '@jest/globals';
import type { Client } from '@modelcontextprotocol/sdk/client/index.js';

import { cleanupSessionTmpDir } from '../../src/core/execute.js';
import {
  FIXTURES_DIR,
  callTool,
  connectClient,
  makeTempDir,
  removeTempDirs,
  startHttpServer,
  writeFiles,
  type TestHttpServer
} from '../helpers.js';

const BRU_COLLECTION = path.join(FIXTURES_DIR, 'run-collection', 'bru');
const YML_COLLECTION = path.join(FIXTURES_DIR, 'run-collection', 'yml');

// Each run spawns the real `bru` CLI.
jest.setTimeout(60_000);

let client: Client;
let server: TestHttpServer;

beforeAll(async () => {
  [client, server] = await Promise.all([connectClient(), startHttpServer()]);
});

afterAll(async () => {
  await Promise.all([client.close(), server.close()]);
  cleanupSessionTmpDir();
});

beforeEach(() => {
  server.reset();
});

afterEach(removeTempDirs);

const run = ({ variables, ...args }: Record<string, any> = {}) =>
  callTool(client, 'run_collection', {
    collectionPath: BRU_COLLECTION,
    variables: { baseUrl: server.baseUrl, ...variables },
    ...args
  });

describe('run_collection', () => {
  it('runs the whole collection and reports failures per request', async () => {
    const { isError, body } = await run({ variables: { userId: 9 } });

    expect(isError).toBe(true);
    expect(body.ok).toBe(false);
    expect(body.summary).toMatchObject({
      iterations: 1,
      total: 3,
      passed: 2,
      failed: 1,
      errored: 0,
      skipped: 0,
      assertions: { passed: 1, failed: 1 },
      tests: { passed: 1, failed: 0 }
    });
    expect(body.requests.map((r: any) => [r.path, r.outcome, r.status])).toEqual([
      ['users/get-user.bru', 'passed', 200],
      ['users/missing-user.bru', 'failed', 404],
      ['health.bru', 'passed', 200]
    ]);
    expect(body.requests[1].failedChecks).toEqual([{ name: 'res.status: eq 200', error: 'expected 404 to equal 200' }]);
    expect(server.hits).toEqual(['/users/9', '/missing', '/health']);
  });

  it('applies the selected environment', async () => {
    const { isError } = await run({ requests: ['users/get-user.bru'], environment: 'local' });

    expect(isError).toBe(false);
    expect(server.hits).toEqual(['/users/42']);
  });

  it('runs only the selected requests and folders, in the given order', async () => {
    const { body } = await run({ requests: ['health.bru', 'users'], variables: { userId: 5 } });

    expect(body.requests.map((r: any) => r.path)).toEqual(['health.bru', 'users/get-user.bru', 'users/missing-user.bru']);
    expect(server.hits).toEqual(['/health', '/users/5', '/missing']);
  });

  it('stops at the first failure when bail is set', async () => {
    const { body } = await run({ requests: ['users/missing-user.bru', 'health.bru'], bail: true });

    expect(body.requests.map((r: any) => [r.path, r.outcome, r.status])).toEqual([
      ['users/missing-user.bru', 'failed', 404],
      ['health.bru', 'skipped', null]
    ]);
    expect(body.summary).toMatchObject({ total: 2, failed: 1, skipped: 1 });
    expect(server.hits).toEqual(['/missing']);
  });

  it('runs one iteration per row of a data file relative to the collection', async () => {
    const { isError, body } = await run({ requests: ['users/get-user.bru'], dataFile: 'users.csv' });

    expect(isError).toBe(false);
    expect(body.summary).toMatchObject({ iterations: 2, total: 2, passed: 2 });
    expect(body.requests.map((r: any) => r.iteration)).toEqual([0, 1]);
    expect(server.hits).toEqual(['/users/1', '/users/2']);
  });

  it('accepts an absolute data file path', async () => {
    const { isError } = await run({ requests: ['users/get-user.bru'], dataFile: path.join(BRU_COLLECTION, 'users.csv') });

    expect(isError).toBe(false);
    expect(server.hits).toEqual(['/users/1', '/users/2']);
  });

  it('takes the iteration count from the data file over iterations', async () => {
    const { body } = await run({ requests: ['users/get-user.bru'], dataFile: 'users.csv', iterations: 5 });

    expect(body.summary).toMatchObject({ iterations: 2, total: 2 });
  });

  it('runs iterations concurrently when parallel is set', async () => {
    server.holdUntilInFlight = 2;

    const { isError } = await run({ requests: ['users/get-user.bru'], dataFile: 'users.csv', parallel: true });

    expect(isError).toBe(false);
    expect(server.maxInFlight).toBe(2);
  });

  it('repeats the selection for the requested number of iterations', async () => {
    const { isError, body } = await run({ requests: ['health.bru'], iterations: 3 });

    expect(isError).toBe(false);
    expect(body.summary).toMatchObject({ iterations: 3, total: 3, passed: 3 });
    expect(server.hits).toEqual(['/health', '/health', '/health']);
  });

  it('stops the run after timeoutSeconds', async () => {
    server.holdUntilInFlight = 2;

    const { isError, body } = await run({ requests: ['health.bru'], timeoutSeconds: 1 });

    expect(isError).toBe(true);
    expect(body.error).toMatch(/bru run timed out after 1000ms$/);
  });

  it('runs .yml collections and keeps their request paths', async () => {
    const { isError, body } = await run({ collectionPath: YML_COLLECTION, environment: 'dev' });

    expect(isError).toBe(false);
    expect(body.requests).toEqual([
      { path: 'users/get-user.yml', name: 'Get user', outcome: 'passed', status: 200, responseTimeMs: expect.any(Number) }
    ]);
    expect(server.hits).toEqual(['/users/7']);
  });

  it.each([
    ['a JSON object instead of an array', () => 'bruno.json'],
    ['a CSV with only a header', () => path.join(writeFiles(makeTempDir(), { 'empty.csv': 'userId\n' }), 'empty.csv')]
  ])('explains that nothing ran for %s', async (_label, dataFile) => {
    const { isError, body } = await run({ dataFile: dataFile() });

    expect(isError).toBe(true);
    expect(body.summary).toMatchObject({ iterations: 0, total: 0 });
    expect(body.error).toMatch(/^Nothing ran: the data file has no rows/);
    expect(server.hits).toEqual([]);
  });

  describe('input validation', () => {
    // Rejected input must never reach the CLI.
    afterEach(() => {
      expect(server.hits).toEqual([]);
    });

    it('lists every request or folder path that does not exist in the collection', async () => {
      const { isError, body } = await run({ requests: ['nope.bru', '../yml', 'environments', 'Users', 'users'] });

      expect(isError).toBe(true);
      expect(body.error).toBe('Not a request or folder in collection "Run Fixture": nope.bru, ../yml, environments, Users');
      expect(body.availableRequests).toEqual(['users/get-user.bru', 'users/missing-user.bru', 'health.bru']);
    });

    it('rejects an unknown environment', async () => {
      const { isError, body } = await run({ environment: 'production' });

      expect(isError).toBe(true);
      expect(body.error).toBe('The environment "production" doesn\'t exist in the "Run Fixture" collection.');
      expect([...body.availableEnvironments].sort()).toEqual(['local', 'staging']);
    });

    it.each(['missing.csv', 'health.bru', 'users'])('rejects data file "%s"', async (dataFile) => {
      const { isError, body } = await run({ dataFile });

      expect(isError).toBe(true);
      expect(body.error).toBe(`Data file not found or not a .csv/.json file: ${dataFile}`);
    });

    it.each(['iterations', 'timeoutSeconds'])('rejects %s below one', async (field) => {
      const { isError, text } = await run({ [field]: 0 });

      expect(isError).toBe(true);
      expect(text).toMatch(new RegExp(`Input validation error: .*at ${field}`));
    });

    it('errors for a path that is not a collection', async () => {
      const { isError, body } = await run({ collectionPath: makeTempDir() });

      expect(isError).toBe(true);
      expect(body.error).toMatch(/^No Bruno collection at/);
    });
  });
});

import { describe, expect, it } from '@jest/globals';

import { formatRunResult } from '../../src/core/execute.js';

const rawRun = (report: unknown, exitCode = 0, stderr = '') => ({
  exitCode,
  report,
  stderr,
  stdout: '',
  reportParseError: null
});

const summary = (overrides: Record<string, number> = {}) => ({
  totalRequests: 0,
  passedRequests: 0,
  failedRequests: 0,
  errorRequests: 0,
  skippedRequests: 0,
  totalAssertions: 0,
  passedAssertions: 0,
  failedAssertions: 0,
  totalTests: 0,
  passedTests: 0,
  failedTests: 0,
  passedPreRequestTests: 0,
  failedPreRequestTests: 0,
  passedPostResponseTests: 0,
  failedPostResponseTests: 0,
  ...overrides
});

const entry = (overrides: Record<string, unknown>) => ({
  status: 'pass',
  response: { status: 200, responseTime: 10 },
  assertionResults: [],
  testResults: [],
  preRequestTestResults: [],
  postResponseTestResults: [],
  iterationIndex: 0,
  ...overrides
});

describe('formatRunResult', () => {
  it('rolls up each request with its outcome and failed checks', () => {
    const report = [
      {
        iterationIndex: 0,
        summary: summary({ totalRequests: 5, passedRequests: 1, failedRequests: 2, errorRequests: 1, skippedRequests: 1 }),
        results: [
          entry({
            path: 'users/get-user',
            name: 'Get user',
            assertionResults: [{ lhsExpr: 'res.status', rhsExpr: 'eq 200', status: 'pass' }],
            testResults: [{ description: 'returns the user', status: 'pass' }]
          }),
          entry({
            path: 'users/missing-user',
            name: 'Missing user',
            response: { status: 404, responseTime: 8 },
            assertionResults: [
              { lhsExpr: 'res.status', rhsExpr: 'eq 200', status: 'fail', error: 'expected 404 to equal 200' }
            ]
          }),
          entry({
            path: 'scripted',
            name: 'Scripted',
            postResponseTestResults: [
              { description: 'Post-Response Script Error', status: 'fail', error: 'boom', isScriptError: true }
            ]
          }),
          entry({
            path: 'down',
            name: 'Down',
            status: 'error',
            error: 'connect ECONNREFUSED',
            response: { status: 'error', responseTime: 0 }
          }),
          entry({
            path: 'health',
            name: 'Health',
            status: 'skipped',
            skipReason: 'bail',
            response: { status: 'skipped', responseTime: 0 }
          })
        ]
      }
    ];

    const result = formatRunResult(rawRun(report, 1), 'bru', 1234);

    expect(result.ok).toBe(false);
    expect(result.requests).toEqual([
      { path: 'users/get-user.bru', name: 'Get user', outcome: 'passed', status: 200, responseTimeMs: 10 },
      {
        path: 'users/missing-user.bru',
        name: 'Missing user',
        outcome: 'failed',
        status: 404,
        responseTimeMs: 8,
        failedChecks: [{ name: 'res.status: eq 200', error: 'expected 404 to equal 200' }]
      },
      {
        path: 'scripted.bru',
        name: 'Scripted',
        outcome: 'failed',
        status: 200,
        responseTimeMs: 10,
        failedChecks: [{ name: 'Post-Response Script Error', error: 'boom' }]
      },
      {
        path: 'down.bru',
        name: 'Down',
        outcome: 'error',
        status: null,
        responseTimeMs: 0,
        error: 'connect ECONNREFUSED'
      },
      { path: 'health.bru', name: 'Health', outcome: 'skipped', status: null, responseTimeMs: 0 }
    ]);
    expect(result.summary).toMatchObject({ total: 5, passed: 1, failed: 2, errored: 1, skipped: 1, durationMs: 1234 });
  });

  it('keeps the extension the CLI already reports for .yml collections', () => {
    const report = [{ iterationIndex: 0, summary: summary(), results: [entry({ path: 'users/get-user.yml', name: 'Get user' })] }];

    expect(formatRunResult(rawRun(report), 'yml', 0).requests[0].path).toBe('users/get-user.yml');
  });

  it('sums summaries across iterations and tags each request with its iteration', () => {
    const iteration = (iterationIndex: number) => ({
      iterationIndex,
      summary: summary({
        totalRequests: 1,
        passedRequests: 1,
        totalAssertions: 1,
        passedAssertions: 1,
        passedTests: 1,
        passedPreRequestTests: 1,
        passedPostResponseTests: 1
      }),
      results: [entry({ path: 'health', name: 'Health', iterationIndex })]
    });

    const result = formatRunResult(rawRun([iteration(0), iteration(1)]), 'bru', 0);

    expect(result.ok).toBe(true);
    expect(result.summary).toMatchObject({
      iterations: 2,
      total: 2,
      passed: 2,
      assertions: { passed: 2, failed: 0 },
      tests: { passed: 6, failed: 0 }
    });
    expect(result.requests.map((r: any) => r.iteration)).toEqual([0, 1]);
  });

  it('tags skipped-file entries, which carry no iterationIndex, with their iteration', () => {
    const { iterationIndex: _, ...skippedFile } = entry({ path: 'broken.bru', name: 'broken.bru', status: 'skipped' });
    const report = [0, 1].map((iterationIndex) => ({
      iterationIndex,
      summary: summary({ totalRequests: 1, skippedRequests: 1 }),
      results: [skippedFile]
    }));

    expect(formatRunResult(rawRun(report), 'bru', 0).requests.map((r: any) => r.iteration)).toEqual([0, 1]);
  });

  it('is not ok when the CLI ran no requests, even with a zero exit code', () => {
    const report = [{ iterationIndex: 0, summary: summary(), results: [] }];

    const result = formatRunResult(rawRun(report, 0), 'bru', 5);

    expect(result.ok).toBe(false);
    expect(result.error).toBe('Nothing ran: no runnable requests were found in the selection.');
  });

  it('omits the iteration field for a single iteration', () => {
    const report = [{ iterationIndex: 0, summary: summary(), results: [entry({ path: 'health', name: 'Health' })] }];

    expect(formatRunResult(rawRun(report), 'bru', 0).requests[0]).not.toHaveProperty('iteration');
  });

  it('explains an empty report from a data file with no rows', () => {
    const result = formatRunResult(rawRun([], 0), 'bru', 5);

    expect(result.ok).toBe(false);
    expect(result.error).toMatch(/^Nothing ran: the data file has no rows/);
  });

  it('surfaces stderr as the error when the CLI produced no report', () => {
    const result = formatRunResult(rawRun(null, 1, 'Path not found: /x/nope.bru\n'), 'bru', 5);

    expect(result.ok).toBe(false);
    expect(result.error).toBe('Path not found: /x/nope.bru');
    expect(result.requests).toEqual([]);
    expect(result.summary).toMatchObject({ iterations: 0, total: 0 });
  });
});

import { afterAll, afterEach, beforeAll, describe, expect, it } from '@jest/globals';
import type { Client } from '@modelcontextprotocol/sdk/client/index.js';

import {
  BRU_COLLECTION,
  YML_COLLECTION,
  callTool,
  connectClient,
  makeTempDir,
  removeTempDirs,
  writeFiles
} from '../helpers.js';

let client: Client;

beforeAll(async () => {
  client = await connectClient();
});

afterAll(async () => {
  await client.close();
});

afterEach(removeTempDirs);

describe('list_environments', () => {
  it('lists each environment with its variable count and whether it has secrets', async () => {
    const { isError, body } = await callTool(client, 'list_environments', { collectionPath: BRU_COLLECTION });

    expect(isError).toBe(false);
    expect([...body.environments].sort((a: any, b: any) => a.name.localeCompare(b.name))).toEqual([
      { name: 'local', variableCount: 4, hasSecrets: true },
      { name: 'staging', variableCount: 1, hasSecrets: false }
    ]);
  });

  it('works for .yml collections', async () => {
    const { body } = await callTool(client, 'list_environments', { collectionPath: YML_COLLECTION });

    expect(body.environments).toEqual([{ name: 'dev', variableCount: 3, hasSecrets: true }]);
  });

  it('lists only environments in the collection format, the ones bru run can load', async () => {
    const collectionPath = writeFiles(makeTempDir(), {
      'bruno.json': '{"version":"1","name":"Mixed"}',
      'environments/local.bru': 'vars {\n  baseUrl: http://localhost\n}\n',
      'environments/local.yml': 'name: local\nvariables: []\n',
      'environments/ci.yml': 'name: ci\nvariables: []\n'
    });

    const { body } = await callTool(client, 'list_environments', { collectionPath });

    expect(body.environments).toEqual([{ name: 'local', variableCount: 1, hasSecrets: false }]);
  });

  it('adds a hint when the collection has no environments', async () => {
    const collectionPath = writeFiles(makeTempDir(), { 'bruno.json': '{"version":"1","name":"Empty"}' });

    const { isError, body } = await callTool(client, 'list_environments', { collectionPath });

    expect(isError).toBe(false);
    expect(body.environments).toEqual([]);
    expect(body.hint).toMatch(/no environments/);
  });

  it('reports a malformed environment without failing the others or crashing the server', async () => {
    const collectionPath = writeFiles(makeTempDir(), {
      'bruno.json': '{"version":"1","name":"Broken"}',
      'environments/good.bru': 'vars {\n  baseUrl: http://localhost\n}\n',
      'environments/broken.bru': 'vars {\n  baseUrl: x\n'
    });

    const { isError, body } = await callTool(client, 'list_environments', { collectionPath });

    expect(isError).toBe(false);
    const byName = Object.fromEntries(body.environments.map((env: any) => [env.name, env]));
    expect(byName.good).toEqual({ name: 'good', variableCount: 1, hasSecrets: false });
    expect(byName.broken.error).toMatch(/^Could not parse environment/);
  });

  it('errors for a path that is not a collection', async () => {
    const { isError, body } = await callTool(client, 'list_environments', { collectionPath: makeTempDir() });

    expect(isError).toBe(true);
    expect(body.error).toMatch(/^No Bruno collection at/);
  });
});

describe('get_environment', () => {
  it('returns variables with secret values redacted', async () => {
    const { isError, body } = await callTool(client, 'get_environment', { collectionPath: BRU_COLLECTION, name: 'local' });

    expect(isError).toBe(false);
    expect(body).toEqual({
      name: 'local',
      variables: [
        { name: 'baseUrl', value: 'http://127.0.0.1:1', enabled: true, secret: false },
        { name: 'legacyUrl', value: 'http://legacy.local', enabled: false, secret: false },
        { name: 'userId', value: '42', enabled: true, secret: false },
        { name: 'apiKey', value: '<redacted>', enabled: true, secret: true }
      ]
    });
  });

  it('never returns a secret value stored on disk', async () => {
    const { isError, text } = await callTool(client, 'get_environment', { collectionPath: YML_COLLECTION, name: 'dev' });

    expect(isError).toBe(false);
    expect(text).not.toContain('do-not-leak');
    expect(text).toContain('<redacted>');
  });

  it.each(['production', 'Local', '../health', 'environments/local'])('errors for unknown environment "%s"', async (name) => {
    const { isError, body } = await callTool(client, 'get_environment', { collectionPath: BRU_COLLECTION, name });

    expect(isError).toBe(true);
    expect(body.error).toContain(`"${name}" doesn't exist`);
    expect([...body.availableEnvironments].sort()).toEqual(['local', 'staging']);
  });

  it('errors for a malformed environment file', async () => {
    const collectionPath = writeFiles(makeTempDir(), {
      'bruno.json': '{"version":"1","name":"Broken"}',
      'environments/broken.bru': 'vars {\n  baseUrl: x\n'
    });

    const { isError, body } = await callTool(client, 'get_environment', { collectionPath, name: 'broken' });

    expect(isError).toBe(true);
    expect(body.error).toMatch(/^Could not parse environment "broken"/);
  });
});

